[
  {
    "statement": "In a controlled laboratory study, genetically modified maize expressing Bacillus thuringiensis kurstaki (Btk) toxin for European corn borer control showed specific effectiveness parameters.",
    "citations": []
  },
  {
    "statement": "The pollen from genetically modified maize expressing the Btk toxin did not reduce the survival of eastern tiger swallowtail caterpillars more than pollen from non-genetically modified maize.",
    "citations": []
  },
  {
    "statement": "The pollen from genetically modified maize expressing the Btk toxin did not reduce the survival of spicebush swallowtail caterpillars more than pollen from non-genetically modified maize.",
    "citations": []
  },
  {
    "statement": "The pollen from genetically modified maize expressing the Btk toxin did not reduce the growth of eastern tiger swallowtail caterpillars more than pollen from non-genetically modified maize.",
    "citations": []
  },
  {
    "statement": "The pollen from genetically modified maize expressing the Btk toxin did not reduce the growth of spicebush swallowtail caterpillars more than pollen from non-genetically modified maize.",
    "citations": []
  },
  {
    "statement": "A study evaluated the effects on butterflies and moths of using genetically modified crops that produce pesticide to replace conventional pesticide application.",
    "citations": []
  }
]

[
  {
    "statement": "Several natural pest control methods show cost-effectiveness.",
    "citations": [
      "753",
      "750",
      "724",
      "729"
    ]
  },
  {
    "statement": "Specific data for natural pest control methods in arid desert environments is limited.",
    "citations": []
  },
  {
    "statement": "Push-pull systems demonstrate strong economic benefits.",
    "citations": [
      "753"
    ]
  },
  {
    "statement": "Two studies in Kenya and a review found that push-pull systems provided greater economic benefits.",
    "citations": [
      "753"
    ]
  },
  {
    "statement": "One study showed push-pull systems had higher production costs only in the first year, but equal or lower costs in the following five years.",
    "citations": [
      "753"
    ]
  },
  {
    "statement": "The push-pull system increased parasitism of stem borer larvae.",
    "citations": [
      "753"
    ]
  },
  {
    "statement": "The push-pull system had more natural predators in overall totals and a greater abundance of different predator groups.",
    "citations": [
      "753"
    ]
  },
  {
    "statement": "Threshold-based pesticide use showed cost-effectiveness across multiple studies.",
    "citations": [
      "750"
    ]
  },
  {
    "statement": "Nine studies found that fewer pesticide applications were needed with threshold-based pesticide use.",
    "citations": [
      "750"
    ]
  },
  {
    "statement": "Three studies found or predicted lower production costs with threshold-based pesticide use.",
    "citations": [
      "750"
    ]
  },
  {
    "statement": "Threshold-based pesticide use maintained similar yields and crop damage compared to conventional spraying regimes.",
    "citations": [
      "750"
    ]
  },
  {
    "statement": "Growing plants that produce chemicals to attract natural enemies showed effectiveness in attracting natural enemies.",
    "citations": [
      "724"
    ]
  },
  {
    "statement": "Growing plants that produce chemicals to attract natural enemies was effective in reducing pest populations or damage across crops including lettuce, orange, safflower and sorghum.",
    "citations": [
      "724"
    ]
  },
  {
    "statement": "One study found that growing plants that produce chemicals to attract natural enemies increased crop yield.",
    "citations": [
      "724"
    ]
  },
  {
    "statement": "Beetle banks demonstrated economic potential.",
    "citations": [
      "729"
    ]
  },
  {
    "statement": "One study and a review showed beetle banks could make economic savings if the beetle banks prevented pests from reaching spray thresholds or causing 5% yield loss.",
    "citations": [
      "729"
    ]
  },
  {
    "statement": "None of the documented studies specifically evaluated these natural pest control methods in arid or desert environments.",
    "citations": []
  },
  {
    "statement": "The lack of specific evaluation limits the direct application of cost-effectiveness data to arid or desert conditions.",
    "citations": []
  }
]

[
  {
    "statement": "Mass-emergence devices show limited and mixed effectiveness for increasing natural enemy populations on farms.",
    "citations": []
  },
  {
    "statement": "One randomised, replicated, controlled study in Switzerland found higher parasitism at one site but no effect at another site when mass-emergence devices were used in urban areas.",
    "citations": [
      "775"
    ]
  },
  {
    "statement": "A study in Switzerland found no effect on pest damage to horse chestnut trees from the use of mass-emergence devices.",
    "citations": [
      "775"
    ]
  },
  {
    "statement": "The only direct evidence available for mass-emergence devices comes from a single study.",
    "citations": [
      "775"
    ]
  },
  {
    "statement": "The effectiveness of mass-emergence devices may be site-dependent.",
    "citations": []
  },
  {
    "statement": "The use of mass-emergence devices may not consistently translate to reduced pest damage even when parasitism increases.",
    "citations": []
  }
]

[
  {
    "statement": "There is limited direct evidence specifically addressing how large-scale climate change impacts the effectiveness of natural pest control strategies.",
    "citations": []
  },
  {
    "statement": "Available information primarily focuses on individual pest management techniques rather than climate change effects on these strategies.",
    "citations": []
  },
  {
    "statement": "Natural pest control strategies include various approaches with varying effectiveness.",
    "citations": []
  },
  {
    "statement": "Planting flowers can increase pest reduction and lead to higher proportions of parasitized pests in fields.",
    "citations": [
      "1400"
    ]
  },
  {
    "statement": "The effects of planting flowers on pest numbers can be inconsistent.",
    "citations": [
      "1400"
    ]
  },
  {
    "statement": "Using ground cover in orchards and vineyards shows mixed results for pest regulation.",
    "citations": [
      "1395"
    ]
  },
  {
    "statement": "Some studies on ground cover in orchards and vineyards found increased parasitism of leafhopper eggs, while others showed inconsistent differences.",
    "citations": [
      "1395"
    ]
  },
  {
    "statement": "Creating beetle banks can increase invertebrate predators and reduce pests in surrounding crops.",
    "citations": [
      "729"
    ]
  },
  {
    "statement": "The largest pest reductions from beetle banks occur in areas closest to the beetle banks.",
    "citations": [
      "729"
    ]
  },
  {
    "statement": "Some natural pest control strategies show temporal sensitivity that could be relevant to climate impacts.",
    "citations": []
  },
  {
    "statement": "Delayed mowing or grazing affects natural enemy populations.",
    "citations": [
      "727"
    ]
  },
  {
    "statement": "Studies on delayed mowing or grazing found mixed effects on predator groups, with some finding more pest insects in late-cut plots.",
    "citations": [
      "727"
    ]
  },
  {
    "statement": "Alley cropping shows variable effects on parasitism that depend on study sites, sampling dates, and pest life stages.",
    "citations": [
      "718"
    ]
  },
  {
    "statement": "The effects of ant exclusion for pest protection vary between natural enemy species, sampling dates, and sites.",
    "citations": [
      "886"
    ]
  },
  {
    "statement": "There is no specific information about how climate change factors such as temperature increases, altered precipitation patterns, or shifting seasonal timing directly affect the effectiveness of natural pest control strategies.",
    "citations": []
  }
]
